{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.ru_eu_nu as WITH base AS ( SELECT customer_id, order_name, order_timestamp::date AS order_date FROM snitch_db.maplemonk.fact_items_snitch ), first_order AS ( SELECT customer_id, MIN(order_date) AS first_order_date FROM base GROUP BY customer_id ), classified_orders AS ( SELECT b.customer_id, b.order_name, b.order_date, f.first_order_date, MAX(b2.order_date) AS last_order_date FROM base b LEFT JOIN base b2 ON b.customer_id = b2.customer_id AND b2.order_date < b.order_date LEFT JOIN first_order f ON b.customer_id = f.customer_id GROUP BY b.customer_id, b.order_name, b.order_date, f.first_order_date ), geo_details as ( select customer_id, pincode, CASE WHEN Pincode LIKE \'11%\' THEN \'Delhi\' WHEN Pincode LIKE \'12%\' OR Pincode LIKE \'13%\' THEN \'Haryana\' WHEN Pincode LIKE \'14%\' OR Pincode LIKE \'15%\' THEN \'Punjab\' WHEN Pincode LIKE \'16%\' THEN \'Chandigarh\' WHEN Pincode LIKE \'17%\' THEN \'Himachal Pradesh\' WHEN Pincode LIKE \'18%\' OR Pincode LIKE \'19%\' THEN \'Jammu and Kashmir, Ladakh\' WHEN Pincode BETWEEN \'200000\' AND \'289999\' THEN \'Uttar Pradesh, Uttarakhand\' WHEN Pincode BETWEEN \'300000\' AND \'349999\' THEN \'Rajasthan\' WHEN Pincode BETWEEN \'360000\' AND \'399999\' AND Pincode NOT LIKE \'396%\' THEN \'Gujarat\' WHEN Pincode LIKE \'396%\' THEN \'Dadra & Nagar Haveli and Daman & Diu\' WHEN Pincode BETWEEN \'400000\' AND \'449999\' AND Pincode NOT LIKE \'403%\' THEN \'Maharashtra\' WHEN Pincode LIKE \'403%\' THEN \'Goa\' WHEN Pincode BETWEEN \'450000\' AND \'489999\' THEN \'Madhya Pradesh\' WHEN Pincode LIKE \'49%\' THEN \'Chhattisgarh\' WHEN Pincode LIKE \'50%\' THEN \'Telangana\' WHEN Pincode BETWEEN \'510000\' AND \'539999\' THEN \'Andhra Pradesh\' WHEN Pincode BETWEEN \'560000\' AND \'599999\' THEN \'Karnataka\' WHEN Pincode BETWEEN \'600000\' AND \'669999\' THEN \'Tamil Nadu\' WHEN Pincode LIKE \'605%\' THEN \'Puducherry\' WHEN Pincode BETWEEN \'670000\' AND \'699999\' AND Pincode NOT LIKE \'682%\' THEN \'Kerala\' WHEN Pincode LIKE \'682%\' THEN \'Lakshadweep\' WHEN Pincode BETWEEN \'700000\' AND \'749999\' AND Pincode NOT LIKE \'737%\' AND Pincode NOT LIKE \'744%\' THEN \'West Bengal\' WHEN Pincode LIKE \'737%\' THEN \'Sikkim\' WHEN Pincode LIKE \'744%\' THEN \'Andaman and Nicobar Islands\' WHEN Pincode BETWEEN \'750000\' AND \'779999\' THEN \'Odisha\' WHEN Pincode LIKE \'78%\' THEN \'Assam\' WHEN Pincode BETWEEN \'790000\' AND \'799999\' THEN \'Arunachal Pradesh\' WHEN Pincode BETWEEN \'793000\' AND \'794999\' THEN \'Meghalaya\' WHEN Pincode LIKE \'795%\' THEN \'Manipur\' WHEN Pincode LIKE \'796%\' THEN \'Mizoram\' WHEN Pincode BETWEEN \'797000\' AND \'798999\' THEN \'Nagaland\' WHEN Pincode LIKE \'799%\' THEN \'Tripura\' WHEN Pincode BETWEEN \'800000\' AND \'859999\' THEN \'Bihar, Jharkhand\' WHEN Pincode BETWEEN \'900000\' AND \'999999\' THEN \'Army Postal Service\' ELSE \'Unknown\' END AS state from snitch_db.maplemonk.fact_items_snitch qualify row_number() over (partition by customer_id order by order_timestamp::date desc) = 1 ), final AS ( SELECT a.customer_id, order_name, order_date, state, pincode, CASE WHEN order_date = first_order_date THEN \'New User\' WHEN last_order_date >= DATEADD(day, -90, order_date) THEN \'Existing User\' ELSE \'Repeat User\' END AS customer_type FROM classified_orders a left join geo_details b on a.customer_id = b.customer_id ) SELECT order_date, customer_type, state, pincode, COUNT(DISTINCT customer_id) AS customer_count FROM final group by 1,2,3,4 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            